glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif

void main () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 color;
  float percent;
  float radius;
  float clockwise;
};

void main () {
  vec2 dir = v_uv0 - vec2(0.5, 0.5);
  float distance = length(dir);
  if (distance > radius) {
    discard;
  } else {
    float degree = 360.0 * percent;
    float x = v_uv0.x;
    float y = v_uv0.y;
    const float deg2rad = 0.01745329;
    if (clockwise == 0.0) {
      float _degree = atan(0.5 - y, 0.5 - x) / deg2rad - 180.0;
      if (_degree <= -90.0 && _degree >= -360.0) {
        if (_degree < - degree - 90.0) {
          discard;
        }
      } else {
        if (_degree < 270.0 - degree) {
          discard;
        }
      }
    } else {
      float _degree = atan(0.5 - y, 0.5 - x) / deg2rad + 180.0;
      if (_degree >= 0.0 && _degree <= 270.0) {
        if (_degree > degree - 90.0) {
          discard;
        }
      } else {
        if (_degree - 270.0 > degree) {
          discard;
        }
      }
    }
  }
  vec4 o = color * texture2D(texture, v_uv0).rgba;
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

